import { isNavigable, type SeaMapDefinition } from "@pirate-sea-race/content";
import { distanceSquared, seaLineOfSight, tileCentre, tileOf, type EncounterPoint } from "./geometry.js";

/** Where a draw or cancellation returns its two players, in the duel's player order. */
export interface SeparateReturnRequest {
  /** The encounter position: between the two players where the hit landed. */
  readonly encounter: EncounterPoint;
  /** Each player's own position when the hit landed. */
  readonly players: readonly [EncounterPoint, EncounterPoint];
  /** Sub-units: the two points are at least this far apart... */
  readonly minSeparation: number;
  /** ...and each is within this far of the encounter position. */
  readonly maxDistance: number;
}

export interface RespawnRequest {
  readonly encounter: EncounterPoint;
  /** The loser's own position when the hit landed. */
  readonly own: EncounterPoint;
  /** Every other active player's position (§6: away from nearby opponents). */
  readonly opponents: readonly EncounterPoint[];
  /** Sub-units: a dock is clear when no opponent is this close to it. */
  readonly clearRadius: number;
}

export interface RespawnPoint {
  readonly x: number;
  readonly y: number;
  /** The dock the loser respawns at, or null where the mode has no docks. */
  readonly dockId: number | null;
}

/**
 * What differs between the sea and the islands: line of sight and where a duel's players return. Each is a pure
 * function of its arguments; the step calls it with the duel's mode.
 */
export interface ModeRules {
  lineOfSight(from: EncounterPoint, to: EncounterPoint): boolean;
  separateReturn(request: SeparateReturnRequest): readonly [EncounterPoint, EncounterPoint];
  respawnPoint(request: RespawnRequest): RespawnPoint;
}

/**
 * The sea (§6 at sea), fully specified:
 * - line of sight: the supercover line between the ships' tiles touches no land;
 * - a draw returns both ships to the centres of two distinct navigable tiles within `maxDistance` of the encounter
 *   and at least `minSeparation` apart, the pair nearest (by the sum of squared distances) to where each ship was,
 *   ties to the lower first tile then the lower second tile, row-major; a sea with no such pair leaves each ship
 *   where it was;
 * - a loser respawns at the centre of the dock nearest the encounter with no opponent within `clearRadius`, ties to
 *   the lower dock id; if every dock has one, the dock farthest from its nearest opponent, ties to the lower id.
 */
export function seaModeRules(map: SeaMapDefinition): ModeRules {
  if (map.docks.length === 0) throw new RangeError(`${map.name} has no dock to respawn at`);
  const docks = map.docks.map((dock) => ({ id: dock.id, point: tileCentre(map, dock) }));
  return {
    lineOfSight: (from, to) => seaLineOfSight(map, from, to),

    separateReturn({ encounter, players, minSeparation, maxDistance }) {
      const reach = Math.ceil(maxDistance / map.subUnitsPerTile) + 1;
      const centre = tileOf(map, encounter);
      const candidates: EncounterPoint[] = [];
      for (let tileY = centre.tileY - reach; tileY <= centre.tileY + reach; tileY++) {
        for (let tileX = centre.tileX - reach; tileX <= centre.tileX + reach; tileX++) {
          if (!isNavigable(map, tileX, tileY)) continue;
          const point = tileCentre(map, { tileX, tileY });
          if (distanceSquared(encounter, point) <= maxDistance * maxDistance) candidates.push(point);
        }
      }
      const [a, b] = players;
      const toA = candidates.map((point) => distanceSquared(a, point));
      const toB = candidates.map((point) => distanceSquared(b, point));
      let best: { cost: number; p: number; q: number } | null = null;
      for (let p = 0; p < candidates.length; p++) {
        for (let q = 0; q < candidates.length; q++) {
          if (p === q || distanceSquared(candidates[p]!, candidates[q]!) < minSeparation * minSeparation) continue;
          const cost = toA[p]! + toB[q]!;
          // Strictly less keeps the first pair in (p, q) order among equals.
          if (best === null || cost < best.cost) best = { cost, p, q };
        }
      }
      if (best === null) return [{ x: a.x, y: a.y }, { x: b.x, y: b.y }];
      return [candidates[best.p]!, candidates[best.q]!];
    },

    respawnPoint({ encounter, opponents, clearRadius }) {
      const nearestOpponent = (point: EncounterPoint) =>
        opponents.reduce((nearest, opponent) => Math.min(nearest, distanceSquared(point, opponent)), Number.MAX_SAFE_INTEGER);
      let chosen: { id: number; point: EncounterPoint; key: number } | null = null;
      for (const dock of docks) {
        if (nearestOpponent(dock.point) <= clearRadius * clearRadius) continue;
        const key = distanceSquared(encounter, dock.point);
        if (chosen === null || key < chosen.key) chosen = { ...dock, key };
      }
      if (chosen === null) {
        for (const dock of docks) {
          const key = nearestOpponent(dock.point);
          if (chosen === null || key > chosen.key) chosen = { ...dock, key };
        }
      }
      const { id, point } = chosen!;
      return { x: point.x, y: point.y, dockId: id };
    },
  };
}

/**
 * The islands, as a placeholder until walking on islands exists (`objectives-endgame` replaces it): nothing blocks
 * line of sight, and every return stays at the player's own position.
 */
export const footPlaceholderRules: ModeRules = {
  lineOfSight: () => true,
  separateReturn: ({ players: [a, b] }) => [
    { x: a.x, y: a.y },
    { x: b.x, y: b.y },
  ],
  respawnPoint: ({ own }) => ({ x: own.x, y: own.y, dockId: null }),
};
import { HEADING_COUNT, Terrain, terrainAt, type SeaMapDefinition } from "@pirate-sea-race/content";
import { HEADING_DX, HEADING_DY, normalizeHeading } from "../heading.js";

/**
 * The encounter geometry, defined once (docs/encounters.md): integer sub-units, squared distances, the 64-heading
 * table. Nothing here rounds a fraction or calls a transcendental function.
 */

/** A point in integer sub-units. */
export interface EncounterPoint {
  readonly x: number;
  readonly y: number;
}

/** Squared distance, refusing coordinates whose square would not be an exact integer. */
export function distanceSquared(from: EncounterPoint, to: EncounterPoint): number {
  const dx = to.x - from.x;
  const dy = to.y - from.y;
  const squared = dx * dx + dy * dy;
  if (!Number.isSafeInteger(squared)) throw new RangeError(`(${from.x}, ${from.y}) and (${to.x}, ${to.y}) are too far apart`);
  return squared;
}

/** Within `range` sub-units, centre to centre; a point exactly on the boundary is inside. */
export function withinRange(from: EncounterPoint, to: EncounterPoint, range: number): boolean {
  return distanceSquared(from, to) <= range * range;
}

/**
 * The heading (of 64) pointing most nearly along the offset: the one whose unit vector has the largest dot product
 * with it, ties to the lower heading. A zero offset has no bearing (null).
 */
export function bearing(from: EncounterPoint, to: EncounterPoint): number | null {
  const dx = to.x - from.x;
  const dy = to.y - from.y;
  if (dx === 0 && dy === 0) return null;
  let best = 0;
  let bestDot = dx * HEADING_DX[0]! + dy * HEADING_DY[0]!;
  for (let heading = 1; heading < HEADING_COUNT; heading++) {
    const dot = dx * HEADING_DX[heading]! + dy * HEADING_DY[heading]!;
    if (dot > bestDot) {
      best = heading;
      bestDot = dot;
    }
  }
  return best;
}

/** The circular difference between two headings, 0 to 32. */
export function headingDifference(a: number, b: number): number {
  const difference = normalizeHeading(a - b);
  return Math.min(difference, HEADING_COUNT - difference);
}

/**
 * Whether `to` lies within ±`cone` headings of `heading` seen from `from`. Distance 0 is inside every cone:
 * overlapping ships do not block each other.
 */
export function withinCone(from: EncounterPoint, to: EncounterPoint, heading: number, cone: number): boolean {
  const toward = bearing(from, to);
  return toward === null || headingDifference(toward, heading) <= cone;
}

/** A tile, by its column and row. */
export interface TileCell {
  readonly tileX: number;
  readonly tileY: number;
}

/**
 * Every tile the segment between the centres of two tiles touches: a supercover line. Where it passes exactly
 * through a tile corner, both tiles beside the corner count. The set is the same in either direction; the list runs
 * from `from` to `to`.
 */
export function supercover(from: TileCell, to: TileCell): TileCell[] {
  const nx = Math.abs(to.tileX - from.tileX);
  const ny = Math.abs(to.tileY - from.tileY);
  const sx = to.tileX > from.tileX ? 1 : -1;
  const sy = to.tileY > from.tileY ? 1 : -1;
  let x = from.tileX;
  let y = from.tileY;
  const cells: TileCell[] = [{ tileX: x, tileY: y }];
  let ix = 0;
  let iy = 0;
  while (ix < nx || iy < ny) {
    // Compares where the segment next crosses a vertical and a horizontal tile edge, in exact integers.
    const decision = (1 + 2 * ix) * ny - (1 + 2 * iy) * nx;
    if (decision === 0) {
      cells.push({ tileX: x + sx, tileY: y }, { tileX: x, tileY: y + sy });
      x += sx;
      y += sy;
      ix++;
      iy++;
    } else if (decision < 0) {
      x += sx;
      ix++;
    } else {
      y += sy;
      iy++;
    }
    cells.push({ tileX: x, tileY: y });
  }
  return cells;
}

/** The tile holding a point. */
export function tileOf(map: SeaMapDefinition, point: EncounterPoint): TileCell {
  return { tileX: Math.floor(point.x / map.subUnitsPerTile), tileY: Math.floor(point.y / map.subUnitsPerTile) };
}

/** The centre of a tile, in sub-units. */
export function tileCentre(map: SeaMapDefinition, tile: TileCell): EncounterPoint {
  const half = Math.floor(map.subUnitsPerTile / 2);
  return { x: tile.tileX * map.subUnitsPerTile + half, y: tile.tileY * map.subUnitsPerTile + half };
}

/**
 * Ship line of sight: the supercover line between the centres of the two ships' tiles touches no land. Shoals and
 * docks do not block (ships see over reefs); a tile off the map blocks.
 */
export function seaLineOfSight(map: SeaMapDefinition, from: EncounterPoint, to: EncounterPoint): boolean {
  for (const cell of supercover(tileOf(map, from), tileOf(map, to))) {
    const terrain = terrainAt(map, cell.tileX, cell.tileY);
    if (terrain === undefined || terrain === Terrain.Land) return false;
  }
  return true;
}
import { z } from "zod";
import { formatIssues, type ValidationResult } from "../rules.js";
import { ENGAGEMENT_RANGE_TILES, SIGHT_RADIUS_TILES, WORLD_STEPS_PER_SECOND } from "../sailing.js";

/** §6 at sea: the grapple's telegraphed windup. */
export const GRAPPLE_WINDUP_SECONDS = 1;
/** §6 on islands: the visible lunge. */
export const CHALLENGE_LUNGE_SECONDS = 0.6;
/** §6 on islands: "close range". A placeholder until walking on islands exists. */
export const CHALLENGE_RANGE_TILES = 2;
/** §6: a miss costs this long before the next attempt; the grapple uses the challenge's six seconds. */
export const MISS_COOLDOWN_SECONDS = 6;
/** The hit area at landing: within this many headings (of 64) of the aim locked at the start, ±22.5°. */
export const HIT_CONE_HEADINGS = 4;
/** Target choice at the start: within this many headings of the attacker's own heading, ±45°. */
export const TARGET_CONE_HEADINGS = 8;
/** §14: at most this many 1v1 duels at once, counted from reservation to settlement. */
export const MAX_SIMULTANEOUS_DUELS = 4;
/** §6: the transition's visible countdown. */
export const TRANSITION_COUNTDOWN_SECONDS = 3;
/** §6: a client not ready this long after the reservation forfeits. */
export const READY_TIMEOUT_SECONDS = 10;
/** §2: departure protection from the start of player control. */
export const SPAWN_PROTECTION_SECONDS = 45;
/** §6: the winner's escape protection. */
export const WIN_PROTECTION_SECONDS = 8;
/** §6: a draw's (or a cancellation's) protection. */
export const DRAW_PROTECTION_SECONDS = 8;
/** §6: the loser respawns this long after the fight ended... */
export const RESPAWN_DELAY_SECONDS = 15;
/** ...with this long of protection. */
export const RESPAWN_PROTECTION_SECONDS = 20;
/** §6: a draw returns both players to separate points at least this far apart... */
export const DRAW_RETURN_MIN_SEPARATION_TILES = 3;
/** ...and within this far of the encounter. */
export const DRAW_RETURN_MAX_DISTANCE_TILES = 6;

/** Whole world ticks (20 a second) for a duration in seconds. */
export function secondsToTicks(seconds: number): number {
  return Math.round(seconds * WORLD_STEPS_PER_SECOND);
}

const ticks = z.int().nonnegative();
const headings = z.int().min(0).max(32);

/** One attack kind (§6): the sea grapple or the island challenge. */
export const attackRulesSchema = z.strictObject({
  /** The telegraph: the attempt lands this many ticks after it starts. At least one, so it can be escaped. */
  windupTicks: z.int().positive(),
  /** Centre to centre, at the start and at landing; within the sight radius, so no one attacks what they cannot see. */
  rangeTiles: z.int().positive().max(SIGHT_RADIUS_TILES),
  hitConeHeadings: headings,
  targetConeHeadings: headings,
  missCooldownTicks: ticks,
});

export type AttackRules = z.infer<typeof attackRulesSchema>;

/** The encounter rules of §2, §6 and §14 in world ticks and tiles; the simulation converts tiles to sub-units. */
export const encounterRulesSchema = z
  .strictObject({
    grapple: attackRulesSchema,
    challenge: attackRulesSchema,
    maxDuels: z.int().positive(),
    transitionTicks: ticks,
    readyTimeoutTicks: ticks,
    spawnProtectionTicks: ticks,
    winProtectionTicks: ticks,
    drawProtectionTicks: ticks,
    respawnDelayTicks: ticks,
    respawnProtectionTicks: ticks,
    /** A loser respawns at the nearest dock with no opponent this close (the sight radius, §3). */
    respawnClearRadiusTiles: z.int().positive(),
    drawReturnMinSeparationTiles: z.int().positive(),
    drawReturnMaxDistanceTiles: z.int().positive(),
  })
  .superRefine((rules, ctx) => {
    if (rules.readyTimeoutTicks < rules.transitionTicks) {
      ctx.addIssue({
        code: "custom",
        path: ["readyTimeoutTicks"],
        message: `the ready timeout (${rules.readyTimeoutTicks} ticks) ends before the countdown (${rules.transitionTicks} ticks)`,
      });
    }
    if (rules.drawReturnMinSeparationTiles > 2 * rules.drawReturnMaxDistanceTiles) {
      ctx.addIssue({
        code: "custom",
        path: ["drawReturnMinSeparationTiles"],
