export * from "./timing.js";
export * from "./clock.js";
export * from "./events.js";
export * from "./rollback.js";
export * from "./session.js";
export * from "./authority.js";
import { hashState } from "../hash.js";
import { sanitizeDuelInput, type DuelInputs } from "../duel/input.js";
import { createDuelInputLog } from "../duel/replay.js";
import { snapshotDuel } from "../duel/snapshot.js";
import type { DuelConfig, DuelState, PlayerIndex } from "../duel/state.js";
import { stepDuel } from "../duel/step.js";
import type { DuelInputLog } from "@pirate-sea-race/content/moves";
import { HELD_INPUT_FRAMES, type ConfirmedFrames } from "./rollback.js";

/** One frame bundle every this many frames (20 a second). */
export const BUNDLE_FRAMES = 3;
/** Every this many bundles carries a full snapshot (every 6 frames); the others carry the hash. */
export const SNAPSHOT_EVERY_BUNDLES = 2;

/** How far back the authority remembers which frames it substituted (the client's input lead is at most 30). */
const RECENT_FRAMES = 64;

/** A frame bundle as the server sends it: `substituted` is always present. */
export interface AuthorityBundle extends ConfirmedFrames {
  readonly substituted: number;
}

export interface AuthorityStats {
  /** Frames whose input came from a message, per player. */
  received: [number, number];
  /** Frames where the held input was repeated because none arrived in time, per player. */
  repeated: [number, number];
  /** Frames where neutral was used (no input for more than HELD_INPUT_FRAMES), per player. */
  neutral: [number, number];
  /** Inputs that arrived after their frame was stepped with a substitute; ignored (late input never rewrites a frame). */
  late: [number, number];
  /** Copies of an input already received (each frame travels in two messages), ignored. */
  duplicates: [number, number];
}

/**
 * The server's side of the duel netcode (§15), pure so tests can run it without a network: it steps `stepDuel` once
 * per call with each player's input for that frame, and assembles the frame bundles.
 *
 * - Each frame's input comes from the first message that carried it; later copies are ignored.
 * - An input for a frame already stepped is ignored: late input never rewrites a completed frame.
 * - A player with no input for a frame gets their last input repeated for up to HELD_INPUT_FRAMES (250 ms) after
 *   their last received frame, then neutral. Both count as substitutions and are flagged in the bundle.
 * - Every BUNDLE_FRAMES frames (and on the frame the duel ends) a bundle carries the pairs applied since the last one;
 *   every SNAPSHOT_EVERY_BUNDLES-th bundle, and the last, carries a snapshot, the others the state hash.
 */
export class DuelAuthority {
  readonly stats: AuthorityStats = { received: [0, 0], repeated: [0, 0], neutral: [0, 0], late: [0, 0], duplicates: [0, 0] };
  private current: DuelState;
  private readonly initial: DuelState;
  private readonly pending: [Map<number, number>, Map<number, number>] = [new Map(), new Map()];
  private readonly held: [number, number] = [0, 0];
  private readonly heldFrame: [number | undefined, number | undefined] = [undefined, undefined];
  private readonly scripted: [((state: DuelState) => number) | undefined, ((state: DuelState) => number) | undefined] = [undefined, undefined];
  private readonly applied: DuelInputs[] = [];
  /** Recently stepped frames whose input was substituted, per player, to tell a late input from a redundant copy. */
  private readonly recentSubstitutes: [Set<number>, Set<number>] = [new Set(), new Set()];
  private unsent: { inputs: DuelInputs[]; substituted: number } = { inputs: [], substituted: 0 };
  private bundles = 0;

  constructor(
    private readonly config: DuelConfig,
    initial: DuelState,
  ) {
    this.current = initial;
    this.initial = initial;
  }

  get state(): DuelState {
    return this.current;
  }

  get frame(): number {
    return this.current.frame;
  }

  get over(): boolean {
    return this.current.result !== null;
  }

  /**
   * Inputs from one message: `inputs[k]` is for frame `lastFrame - inputs.length + 1 + k`. Returns how many were
   * new; frames already stepped or already received are ignored.
   */
  receive(player: PlayerIndex, lastFrame: number, inputs: readonly number[]): number {
    const first = lastFrame - inputs.length + 1;
    let fresh = 0;
    inputs.forEach((bits, index) => {
      const frame = first + index;
      if (frame <= this.current.frame) {
        if (this.recentSubstitutes[player].has(frame)) this.stats.late[player]++;
        else this.stats.duplicates[player]++;
      } else if (this.pending[player].has(frame)) this.stats.duplicates[player]++;
      else {
        this.pending[player].set(frame, sanitizeDuelInput(bits));
        fresh++;
      }
    });
    return fresh;
  }

  /** Makes a player's input come from `script` (the practice dummy) instead of messages; undefined undoes it. */
  script(player: PlayerIndex, script: ((state: DuelState) => number) | undefined): void {
    this.scripted[player] = script;
  }

  /** Steps one frame; returns the bundle due after it, if one is. */
  step(): AuthorityBundle | undefined {
    const frame = this.current.frame + 1;
    const index = this.unsent.inputs.length;
    for (const recent of this.recentSubstitutes) recent.delete(frame - RECENT_FRAMES);
    const pair = ([0, 1] as const).map((player) => {
      const script = this.scripted[player];
      if (script !== undefined) return sanitizeDuelInput(script(this.current));
      const received = this.pending[player].get(frame);
      this.pending[player].delete(frame);
      if (received !== undefined) {
        this.held[player] = received;
        this.heldFrame[player] = frame;
        this.stats.received[player]++;
        return received;
      }
      this.unsent.substituted |= 1 << (2 * index + player);
      this.recentSubstitutes[player].add(frame);
      const since = this.heldFrame[player];
      if (since !== undefined && frame - since <= HELD_INPUT_FRAMES) {
        this.stats.repeated[player]++;
        return this.held[player];
      }
      this.stats.neutral[player]++;
      return 0;
    }) as unknown as DuelInputs;
    this.current = stepDuel(this.config, this.current, pair);
    this.applied.push(pair);
    this.unsent.inputs.push(pair);
    if (frame % BUNDLE_FRAMES !== 0 && !this.over) return undefined;
    this.bundles++;
    const withSnapshot = this.bundles % SNAPSHOT_EVERY_BUNDLES === 0 || this.over;
    const bundle: AuthorityBundle = {
      frame,
      inputs: this.unsent.inputs,
      substituted: this.unsent.substituted,
      ...(withSnapshot ? { snapshot: snapshotDuel(this.current) } : { hash: hashState(this.current) }),
    };
    this.unsent = { inputs: [], substituted: 0 };
    return bundle;
  }

  /**
   * A bundle with the current state and no inputs: sent at the fight's start and to a player who (re)joins, so their
   * client can start from it. It confirms nothing; the pairs since the last bundle follow in the next one.
   */
  snapshotBundle(): AuthorityBundle {
    return { frame: this.current.frame, inputs: [], substituted: 0, snapshot: snapshotDuel(this.current) };
  }

  /** Every pair applied so far, as an input log from the initial state (for `replayDuel`). */
  inputLog(): DuelInputLog {
    return createDuelInputLog(this.config, this.initial.frame, this.applied);
  }
}
import type { DuelConfig, DuelState, PlayerIndex } from "../duel/state.js";
import { DuelClock } from "./clock.js";
import type { DuelFeedEvent } from "./events.js";
import { DuelRollback, HISTORY_FRAMES, type ConfirmedFrames, type DuelNetStats } from "./rollback.js";

/** Inputs one message carries (the protocol's MAX_DUEL_INPUTS_PER_MESSAGE): the newest frame and three before it. */
export const INPUTS_PER_MESSAGE = 4;
/** A message goes out once this many new frames are tagged, so each frame travels in two messages. */
export const SEND_EVERY_FRAMES = 2;
/** Messages per second at most (the protocol's DUEL_INPUT_MESSAGES_PER_SECOND), half the server's cap. */
export const MESSAGES_PER_SECOND = 30;
/** Frames the client clock may advance in one tick; a longer gap is caught up over the next ticks. */
export const CATCH_UP_FRAMES = 4;
/** A gap this long (a stall or a hidden tab) is not caught up: the client restarts from the latest snapshot. */
export const RESYNC_FRAMES = 30;

/** An input message as the protocol's `DuelInputMessage`: `inputs` ends with frame `frame`. */
export interface OutgoingDuelInput {
  readonly seq: number;
  readonly frame: number;
  readonly inputs: readonly number[];
}

export interface DuelSessionStats extends DuelNetStats {
  /** Times the clock jumped to the server's frame from the latest snapshot. */
  resyncs: number;
  /** Input messages sent. */
  messages: number;
  /** Messages held back to stay under MESSAGES_PER_SECOND (their frames travel in the next message that goes). */
  throttledSends: number;
}

export interface DuelSessionOptions {
  readonly config: DuelConfig;
  readonly player: PlayerIndex;
  /** The duel's frame-0 state, created from the room's seed exactly as the server created it. */
  readonly initial: DuelState;
  readonly historyFrames?: number;
}

/**
 * One duel client, for the browser and the headless test client alike: the rollback core, the client clock and the
 * input stream in one pure object. The caller owns the transport and the time: it passes probes and frame bundles as
 * they arrive, calls `tick` often (every few milliseconds) with the time and the input held now, and sends whatever
 * `tick` returns.
 *
 * Each tick advances the client's frame towards the server's current frame as the clock estimates it (a fixed-step
 * accumulator on the caller's clock, never the display's frame rate), at most CATCH_UP_FRAMES at a time, or restarts
 * from the latest snapshot after a gap of RESYNC_FRAMES. The input held at client frame `c` is tagged for frame
 * `c + inputDelay`, the same shared delay the server applies to both players, and every SEND_EVERY_FRAMES frames the
 * last INPUTS_PER_MESSAGE tagged frames go out in one message.
 */
export class DuelClientSession {
  readonly rollback: DuelRollback;
  readonly clock = new DuelClock();
  private delay: number | undefined;
  private rtt = 0;
  /** The client's frame on the server's timeline: negative during the countdown. */
  private clientFrame: number | undefined;
  private taggedThrough = 0;
  private sentThrough = 0;
  private seq = 0;
  private readonly sendTimes: number[] = [];
  private throttled = false;
  private readonly counters = { resyncs: 0, messages: 0, throttledSends: 0 };

  constructor(options: DuelSessionOptions) {
    this.rollback = new DuelRollback(options.config, options.player, options.initial, options.historyFrames ?? HISTORY_FRAMES);
  }

  get player(): PlayerIndex {
    return this.rollback.player;
  }

  /** The shared input delay in frames, once the server has chosen it. */
  get inputDelay(): number | undefined {
    return this.delay;
  }

  set inputDelay(frames: number | undefined) {
    this.delay = frames;
  }

  /** The latest round trip the server measured for this client, in milliseconds (0 before the first). */
  get rttMs(): number {
    return this.rtt;
  }

  /** The client's frame on the server's timeline (negative in the countdown), once the clock has a sample. */
  get frame(): number | undefined {
    return this.clientFrame;
  }

  /** The newest frame an input has been tagged for; it moves only when a tick tagged new frames. */
  get lastTaggedFrame(): number {
    return this.taggedThrough;
  }

  /** The predicted state to draw. */
  get state(): DuelState {
    return this.rollback.state;
  }

  /** The newest state stepped from the server's inputs: what the HUD reports as authoritative. */
  get confirmedState(): DuelState {
    return this.rollback.confirmedState;
  }

  get stats(): DuelSessionStats {
    return { ...this.rollback.stats, substitutedFrames: [...this.rollback.stats.substitutedFrames], ...this.counters };
  }

  /** A round-trip probe arrived: the server's frame when it left, and the round trip it last measured. */
  receiveProbe(probe: { readonly frame: number; readonly rtt: number }, nowMs: number): void {
    if (probe.rtt > 0) this.rtt = probe.rtt;
    this.clock.observe(probe.frame, nowMs, this.rtt);
  }

  /** A frame bundle arrived. */
  receiveBundle(bundle: ConfirmedFrames, nowMs: number): void {
    this.clock.observe(bundle.frame, nowMs, this.rtt);
    this.rollback.applyBundle(bundle);
  }

  /**
   * Advances the client to the server's estimated frame at `nowMs`, tags the held input `bits` for the frames that
   * came due, steps the prediction, and returns the input message to send now, if any.
   */
  tick(nowMs: number, bits: number): OutgoingDuelInput | undefined {
    const estimate = this.clock.serverFrameAt(nowMs);
    if (estimate === undefined) return undefined;
    const target = Math.floor(estimate);
    if (this.clientFrame === undefined) this.clientFrame = target;
    const gap = target - this.clientFrame;
    if (gap > RESYNC_FRAMES) {
      this.clientFrame = target;
      if (this.rollback.resync()) this.counters.resyncs++;
    } else if (gap > 0) {
      this.clientFrame += Math.min(gap, CATCH_UP_FRAMES);
    }

    if (this.delay !== undefined) {
      const through = this.clientFrame + this.delay;
      // After a long gap only the frames one message can still carry are worth tagging.
      let frame = Math.max(this.taggedThrough + 1, 1, through - INPUTS_PER_MESSAGE + 1);
      for (; frame <= through; frame++) this.rollback.setLocalInput(frame, bits);
      this.taggedThrough = Math.max(this.taggedThrough, through);
