import { DUEL_UNAVAILABLE_MESSAGE, MATCH_UNAVAILABLE_MESSAGE, PROTOCOL_VERSION, type DummyBehaviour } from "@pirate-sea-race/protocol";
import { startArena } from "./arenaScene.js";
import { createMatch, joinMatch, refusalMessage, serverEndpoint, type MatchRoom } from "./connection.js";
import { DuelClient } from "./duelClient.js";
import { createDuel, joinDuel, type DuelRoom } from "./duelConnection.js";
import { renderHud, type ConnectionStatus } from "./hud.js";
import { InputSender } from "./inputSender.js";
import { KeyboardHelm } from "./keyboard.js";
import { MatchView, type ShipSnapshot } from "./matchView.js";
import { startGame } from "./seaScene.js";

const INPUT_INTERVAL_MS = 1000 / 60;

function element<T extends HTMLElement>(selector: string): T {
  const found = document.querySelector<T>(selector);
  if (found === null) throw new Error(`missing element ${selector}`);
  return found;
}

const landing = element<HTMLElement>("#landing");
const matchSection = element<HTMLElement>("#match");
const createButton = element<HTMLButtonElement>("#create-match");
const joinForm = element<HTMLFormElement>("#join-form");
const joinButton = element<HTMLButtonElement>("#join-match");
const codeInput = element<HTMLInputElement>("#join-code");
const errorText = element<HTMLElement>("#join-error");
const duelSection = element<HTMLElement>("#duel");
const duelButtons = [element<HTMLButtonElement>("#create-duel"), element<HTMLButtonElement>("#practice-duel"), element<HTMLButtonElement>("#join-duel")];
const duelCodeInput = element<HTMLInputElement>("#duel-code");
const duelErrorText = element<HTMLElement>("#duel-error");
const endpoint = serverEndpoint(window.location);

element<HTMLElement>('[data-testid="landing-protocol"]').textContent = String(PROTOCOL_VERSION);

createButton.addEventListener("click", () => void connect(() => createMatch(endpoint)));
joinForm.addEventListener("submit", (event) => {
  event.preventDefault();
  void connect(() => joinMatch(endpoint, codeInput.value));
});

element<HTMLButtonElement>("#create-duel").addEventListener("click", () => void connectDuel(() => createDuel(endpoint, false)));
element<HTMLButtonElement>("#practice-duel").addEventListener("click", () => void connectDuel(() => createDuel(endpoint, true)));
element<HTMLFormElement>("#join-duel-form").addEventListener("submit", (event) => {
  event.preventDefault();
  void connectDuel(() => joinDuel(endpoint, duelCodeInput.value));
});

async function connectDuel(open: () => Promise<DuelRoom>): Promise<void> {
  for (const button of duelButtons) button.disabled = true;
  duelErrorText.textContent = "";
  try {
    const room = await open();
    // Development only: `?rtt=80&jitter=20` delays this socket both ways (README). Vite drops this branch, and the
    // module it imports, from the production build.
    if (import.meta.env.DEV) {
      const { applyDevLatency, devLatencyFromQuery } = await import("./devLatency.js");
      const latency = devLatencyFromQuery(window.location.search);
      if (latency !== undefined) applyDevLatency(room, latency);
    }
    enterDuel(room);
  } catch (error) {
    const message = refusalMessage(error);
    duelErrorText.textContent = message === MATCH_UNAVAILABLE_MESSAGE ? DUEL_UNAVAILABLE_MESSAGE : message;
    for (const button of duelButtons) button.disabled = false;
  }
}

function enterDuel(room: DuelRoom): void {
  landing.hidden = true;
  duelSection.hidden = false;
  const duel = new DuelClient(room, element<HTMLElement>("#duel-hud"));
  const boxes = element<HTMLInputElement>("#show-boxes");
  boxes.addEventListener("change", () => {
    duel.setShowBoxes(boxes.checked);
    boxes.blur();
  });
  const dummy = element<HTMLSelectElement>("#dummy-select");
  dummy.addEventListener("change", () => {
    duel.setDummy(dummy.value as DummyBehaviour);
    dummy.blur();
  });
  const dummyControl = element<HTMLElement>("#dummy-control");
  const showDummyControl = () => {
    dummyControl.hidden = room.state?.practice !== true;
  };
  showDummyControl();
  room.onStateChange(showDummyControl);
  startArena(element<HTMLElement>("#arena"), duel);
}

async function connect(open: () => Promise<MatchRoom>): Promise<void> {
  setBusy(true);
  errorText.textContent = "";
  try {
    enterMatch(await open());
  } catch (error) {
    errorText.textContent = refusalMessage(error);
    setBusy(false);
  }
}

function setBusy(busy: boolean): void {
  createButton.disabled = busy;
  joinButton.disabled = busy;
}

function enterMatch(room: MatchRoom): void {
  landing.hidden = true;
  matchSection.hidden = false;

  const view = new MatchView(room.sessionId);
  const sender = new InputSender({ send: (type, message) => room.send(type, message) });
  const keyboard = new KeyboardHelm(window);
  let status: ConnectionStatus = "connected";

  const refresh = () => {
    const state = room.state;
    if (state?.ships === undefined) return;
    const now = performance.now();
    const ships: ShipSnapshot[] = [...state.ships.values()];
    view.ingest(ships, now);
    sender.observeFrame(state.frame, now);
    renderHud(matchSection, {
      code: state.code,
      protocolVersion: state.protocolVersion,
      custom: state.custom,
      status,
      selfId: room.sessionId,
      players: state.players,
      ships,
    });
  };

  room.onStateChange(refresh);
  room.onLeave(() => {
    status = "disconnected";
    refresh();
  });
  refresh();

  const inputTimer = window.setInterval(() => {
    if (status === "connected") sender.update(keyboard.helm(), performance.now());
    else window.clearInterval(inputTimer);
  }, INPUT_INTERVAL_MS);

  startGame(element<HTMLElement>("#game"), view);
}
import {
  duelFrameBundleSchema,
  DuelMessageType,
  duelProbeSchema,
  type DuelPracticeMessage,
  type DuelProbeReply,
  type DuelRoomPhase,
  type DummyBehaviour,
} from "@pirate-sea-race/protocol";
import { createDuelState, defaultDuelConfig, type DuelState, type PlayerIndex } from "@pirate-sea-race/simulation/duel";
import { DuelClientSession, type DuelFeedEvent } from "@pirate-sea-race/simulation/netcode";
import type { ArenaSource } from "./arenaScene.js";
import type { DuelRoom } from "./duelConnection.js";
import { PendingDuelEvents } from "./duelEvents.js";
import { renderDuelHud, resultText, type DuelConnectionStatus } from "./duelHud.js";
import { DuelKeyboard } from "./duelKeyboard.js";

/** The client ticks this often: far finer than a frame, and independent of the display's refresh rate. */
const TICK_MS = 4;
/** The HUD is redrawn this often. */
const HUD_MS = 50;

const { rules } = defaultDuelConfig.moveset;

/**
 * One browser's duel: the room's messages feed a `DuelClientSession` (the same rollback core the headless test
 * client runs), a 4 ms timer ticks it with the keyboard's input and sends what it returns, the arena draws the
 * predicted state, and the HUD shows the confirmed one. `window.__duel` exposes read-only diagnostics for tests.
 */
export class DuelClient implements ArenaSource {
  private session: DuelClientSession | undefined;
  private status: DuelConnectionStatus = "connected";
  private boxes = false;
  private readonly keyboard: DuelKeyboard;
  private readonly timers: number[] = [];
  private readonly pendingEvents = new PendingDuelEvents();

  constructor(
    private readonly room: DuelRoom,
    private readonly hud: HTMLElement,
  ) {
    this.keyboard = new DuelKeyboard(window);
    room.onMessage(DuelMessageType.Probe, (message: unknown) => {
      const probe = duelProbeSchema.safeParse(message);
      if (!probe.success) return;
      room.send(DuelMessageType.Probe, { id: probe.data.id } satisfies DuelProbeReply);
      this.ensureSession()?.receiveProbe(probe.data, performance.now());
    });
    room.onMessage(DuelMessageType.Frames, (message: unknown) => {
      const bundle = duelFrameBundleSchema.safeParse(message);
      if (bundle.success) this.ensureSession()?.receiveBundle(bundle.data, performance.now());
    });
    room.onDrop(() => {
      this.status = "reconnecting";
    });
    room.onReconnect(() => {
      this.status = "connected";
    });
    room.onLeave(() => {
      this.status = "disconnected";
      this.renderHud();
      for (const timer of this.timers) window.clearInterval(timer);
    });
    this.timers.push(window.setInterval(() => this.tick(), TICK_MS));
    this.timers.push(window.setInterval(() => this.renderHud(), HUD_MS));
    (window as unknown as { __duel: unknown }).__duel = {
      stats: () => this.session?.stats,
      frame: () => this.session?.frame,
      confirmedFrame: () => this.session?.rollback.confirmedFrame,
      lastTaggedFrame: () => this.session?.lastTaggedFrame,
      /** The input bits this client tagged for frames `from` to `to` (0 where none was). */
      taggedInputs: (from: number, to: number) =>
        Array.from({ length: Math.max(0, to - from + 1) }, (_, index) => this.session?.rollback.localInput(from + index) ?? 0),
    };
  }

  /** The developer toggle for hurtboxes and hitboxes. */
  setShowBoxes(show: boolean): void {
    this.boxes = show;
  }

  /** Practice rooms: the dummy idles or guards. */
  setDummy(dummy: DummyBehaviour): void {
    this.room.send(DuelMessageType.Practice, { dummy } satisfies DuelPracticeMessage);
  }

  state(): DuelState | undefined {
    return this.session?.state;
  }

  drainEvents(): DuelFeedEvent[] {
    this.collectEvents();
    return this.pendingEvents.drain();
  }

  stateAt(frame: number): DuelState | undefined {
    return this.session?.rollback.stateAt(frame);
  }

  showBoxes(): boolean {
    return this.boxes;
  }

  banner(): string {
    const state = this.room.state;
    if (state === undefined) return "";
    if (state.phase === "waiting") return state.practice ? "" : "Waiting for an opponent";
    if (state.phase === "countdown") return String(Math.max(1, Math.ceil(state.countdown / 60)));
    if (state.phase === "over") return resultText(state.winner, state.reason);
    return (this.session?.frame ?? 0) < 45 ? "FIGHT" : "";
  }

  private get self(): PlayerIndex | undefined {
    const seat = this.room.state?.seats?.find((entry) => entry.sessionId === this.room.sessionId);
    return seat === undefined ? undefined : (seat.slot as PlayerIndex);
  }

  private ensureSession(): DuelClientSession | undefined {
    if (this.session !== undefined) return this.session;
    const self = this.self;
    const seed = this.room.state?.seed;
    if (self === undefined || seed === undefined) return undefined;
    this.session = new DuelClientSession({ config: defaultDuelConfig, player: self, initial: createDuelState(defaultDuelConfig, { seed }) });
    return this.session;
  }

  private tick(): void {
    const session = this.ensureSession();
    if (session === undefined) return;
    // Once the result is in, nothing the player presses matters any more, but the final bundle is still stepped, so
    // the HUD's health, clock and result end on the server's last frame.
    if (this.room.state?.phase === "over") {
      session.finish();
      this.collectEvents();
      return;
    }
    const delay = this.room.state?.inputDelay ?? 0;
    if (delay > 0) session.inputDelay = delay;
    const tagged = session.lastTaggedFrame;
    const message = session.tick(performance.now(), this.keyboard.bits());
    if (session.lastTaggedFrame > tagged) this.keyboard.framesTagged();
    if (message !== undefined) this.room.send(DuelMessageType.Input, message);
    this.collectEvents();
  }

  /** Events are drained every tick, so none is lost while the arena is not drawing (a hidden tab). */
  private collectEvents(): void {
    this.pendingEvents.collect(this.session?.drainEvents() ?? []);
  }

  private renderHud(): void {
    const state = this.room.state;
    const self = this.self;
    if (state === undefined || self === undefined) return;
    const session = this.ensureSession();
    const connected = [0, 1].map((slot) => state.seats.find((seat) => seat.slot === slot)?.connected ?? false) as [boolean, boolean];
    renderDuelHud(this.hud, {
      code: state.code,
      practice: state.practice,
      phase: state.phase as DuelRoomPhase,
      status: this.status,
      self,
      countdown: state.countdown,
      connected,
      confirmed: session?.confirmedState ?? createDuelState(defaultDuelConfig, { seed: state.seed }),
      maxHealth: rules.maxHealth,
      maxStamina: rules.maxStamina,
      roundFrames: rules.roundFrames,
      overtimeFrames: rules.overtimeFrames,
      rttMs: session?.rttMs ?? 0,
      inputDelay: state.inputDelay,
      corrections: session?.stats.corrections ?? 0,
      result: state.phase === "over" ? { winner: state.winner, reason: state.reason } : undefined,
    });
  }
}
import { Client, type Room } from "@colyseus/sdk";
import { CREATE_TOKEN_BYTES, DUEL_ROOM, formatCreateToken, normalizeMatchCode, PROTOCOL_VERSION } from "@pirate-sea-race/protocol";
import type { DuelRoomStateSchema } from "@pirate-sea-race/server/schema";

export type DuelRoom = Room<unknown, DuelRoomStateSchema>;

/** Creates a duel (or a practice duel against the server's dummy) with a fresh one-time token. */
export function createDuel(endpoint: string, practice: boolean): Promise<DuelRoom> {
  const createToken = formatCreateToken(crypto.getRandomValues(new Uint8Array(CREATE_TOKEN_BYTES)));
  return new Client(endpoint).create<DuelRoomStateSchema>(DUEL_ROOM, {
    protocolVersion: PROTOCOL_VERSION,
    createToken,
    ...(practice ? { practice: true } : {}),
  });
}

export function joinDuel(endpoint: string, code: string): Promise<DuelRoom> {
  return new Client(endpoint).join<DuelRoomStateSchema>(DUEL_ROOM, { protocolVersion: PROTOCOL_VERSION, code: normalizeMatchCode(code) });
}
import { Client, ErrorCode, MatchMakeError, type Room } from "@colyseus/sdk";
import {
  CREATE_TOKEN_BYTES,
  formatCreateToken,
  MATCH_ROOM,
  MATCH_UNAVAILABLE_MESSAGE,
  normalizeMatchCode,
  PROTOCOL_VERSION,
} from "@pirate-sea-race/protocol";
import type { MatchStateSchema } from "@pirate-sea-race/server/schema";

export type MatchRoom = Room<unknown, MatchStateSchema>;

const SERVER_PORT = 2593;

/** The match server: `VITE_SERVER_URL` when set, otherwise port 2593 on the host that served the page. */
export function serverEndpoint(location: Location): string {
  const configured: unknown = import.meta.env["VITE_SERVER_URL"];
  return typeof configured === "string" && configured !== "" ? configured : `${location.protocol}//${location.hostname}:${SERVER_PORT}`;
}

/** Creates a private match, proving to the new room with a fresh one-time token that this client is its creator. */
export function createMatch(endpoint: string): Promise<MatchRoom> {
  const createToken = formatCreateToken(crypto.getRandomValues(new Uint8Array(CREATE_TOKEN_BYTES)));
  return new Client(endpoint).create<MatchStateSchema>(MATCH_ROOM, { protocolVersion: PROTOCOL_VERSION, createToken });
}

export function joinMatch(endpoint: string, code: string): Promise<MatchRoom> {
  return new Client(endpoint).join<MatchStateSchema>(MATCH_ROOM, {
    protocolVersion: PROTOCOL_VERSION,
    code: normalizeMatchCode(code),
  });
}

/**
 * What to tell the player when the server refuses or cannot be reached. The server's own refusals (400, 403, 404,
 * 409, 426) carry readable messages. Colyseus's generic "no rooms found" means the server admitted the request but
 * the match filled up or closed before a seat was reserved, so it must not claim the match is missing. A failed
 * request that never reached the server carries no numeric code (the SDK wraps fetch's error).
 */
export function refusalMessage(error: unknown): string {
  const code = (error as { code?: unknown } | null)?.code;
  if (code === ErrorCode.MATCHMAKE_INVALID_CRITERIA) return MATCH_UNAVAILABLE_MESSAGE;
  if (error instanceof TypeError || (error instanceof MatchMakeError && typeof code !== "number")) {
    return "Cannot reach the match server";
  }
  if (error instanceof Error && error.message !== "") return error.message;
  return "Could not join the match";
}

