import * as Phaser from "phaser";
import { HEADING_COUNT, insideIsland, ISLAND_THEMES, SIGHT_RADIUS_TILES, Terrain, terrainAt } from "@pirate-sea-race/content";
import { defaultSimulationConfig } from "@pirate-sea-race/simulation";
import { followScroll, TILE_PIXELS, VIEW_HEIGHT, VIEW_WIDTH } from "./camera.js";
import { FogOfWar } from "./fog.js";
import { cssColor, slotColor, type MatchView } from "./matchView.js";
import {
  DOCK_COLOR,
  DOCK_PLANK,
  FOG_COLOR,
  GRID_COLOR,
  LAND_COLORS,
  OWN_RING_COLOR,
  SEA_COLOR,
  SHOAL_COLOR,
  SHOAL_FLECK,
  SIGHT_COLOR,
} from "./palette.js";

const { map } = defaultSimulationConfig;
const WORLD_WIDTH = map.widthTiles * TILE_PIXELS;
const WORLD_HEIGHT = map.heightTiles * TILE_PIXELS;
const PIXELS_PER_SUB_UNIT = TILE_PIXELS / map.subUnitsPerTile;
/** The placeholder art was drawn for 16 px tiles; its details scale with the tile. */
const ART_SCALE = TILE_PIXELS / 16;

/** Tile indexes in the generated tileset texture. */
const TILE_SEA = 0;
const TILE_SHOAL = 1;
const TILE_DOCK = 2;
const TILE_LAND = 3;

const MINIMAP_SCALE = 1.25;
const MINIMAP_MARGIN = 8;

/** A ship as drawn this frame, in canvas pixels, for the DOM report tests read. */
export interface DrawnShip {
  readonly id: string;
  readonly x: number;
  readonly y: number;
  readonly color: string;
}

function landTile(tileX: number, tileY: number): number {
  const theme = map.islands.find((island) => insideIsland(island, tileX, tileY))?.theme ?? "tropical";
  return TILE_LAND + ISLAND_THEMES.indexOf(theme);
}

function tileIndex(tileX: number, tileY: number): number {
  switch (terrainAt(map, tileX, tileY)) {
    case Terrain.Land:
      return landTile(tileX, tileY);
    case Terrain.Shoal:
      return TILE_SHOAL;
    case Terrain.Dock:
      return TILE_DOCK;
    default:
      return TILE_SEA;
  }
}

function tileColor(tileX: number, tileY: number): number {
  const index = tileIndex(tileX, tileY);
  if (index >= TILE_LAND) return LAND_COLORS[ISLAND_THEMES[index - TILE_LAND]!];
  return [SEA_COLOR, SHOAL_COLOR, DOCK_COLOR][index]!;
}

/**
 * Draws the sea: the tile map from content, the ships the server sent at interpolated positions, a camera that
 * follows the player's ship, the sight circle, and a minimap whose fog clears along the player's path. Each frame
 * it records what it drew in data attributes on the report element (`data-drawn-ships`, `data-camera`,
 * `data-fog-revealed`, and once `data-minimap`: the minimap's left, top and scale on the canvas) for the browser tests.
 */
export class SeaScene extends Phaser.Scene {
  private readonly shipGraphics = new Map<string, Phaser.GameObjects.Graphics>();
  private readonly fog = new FogOfWar(map.widthTiles, map.heightTiles, SIGHT_RADIUS_TILES);
  private minimap!: Phaser.Textures.CanvasTexture;
  private minimapMarks!: Phaser.GameObjects.Graphics;
  private sight!: Phaser.GameObjects.Graphics;
  private lastReport = "";

  constructor(
    private readonly view: MatchView,
    private readonly report: HTMLElement,
  ) {
    super("sea");
  }

  create(): void {
    this.createTerrain();
    this.sight = this.add.graphics();
    this.sight.lineStyle(1, SIGHT_COLOR, 0.45);
    this.sight.strokeCircle(0, 0, SIGHT_RADIUS_TILES * TILE_PIXELS);
    this.sight.setDepth(1);
    this.createMinimap();
  }

  /** The tile map, as a Phaser tilemap over a tileset texture drawn here in placeholder colours. */
  private createTerrain(): void {
    const kinds = TILE_LAND + ISLAND_THEMES.length;
    const tileset = this.textures.createCanvas("terrain-tiles", kinds * TILE_PIXELS, TILE_PIXELS)!;
    const context = tileset.getContext();
    const paint = (index: number, color: number) => {
      context.fillStyle = cssColor(color);
      context.fillRect(index * TILE_PIXELS, 0, TILE_PIXELS, TILE_PIXELS);
    };
    paint(TILE_SEA, SEA_COLOR);
    paint(TILE_SHOAL, SHOAL_COLOR);
    context.fillStyle = cssColor(SHOAL_FLECK);
    for (const [x, y] of [[3, 4], [10, 2], [6, 10], [13, 12], [2, 13]] as const) {
      context.fillRect(TILE_SHOAL * TILE_PIXELS + Math.round(x * ART_SCALE), Math.round(y * ART_SCALE), 2 * ART_SCALE, 2 * ART_SCALE);
    }
    paint(TILE_DOCK, DOCK_COLOR);
    context.fillStyle = cssColor(DOCK_PLANK);
    for (const y of [4, 9, 14]) context.fillRect(TILE_DOCK * TILE_PIXELS, Math.round(y * ART_SCALE), TILE_PIXELS, 1);
    ISLAND_THEMES.forEach((theme, index) => paint(TILE_LAND + index, LAND_COLORS[theme]));
    tileset.refresh();

    // Open sea is left empty (-1): the camera's background is the sea, so the layer draws only the few land, shoal
    // and dock tiles in view. Drawing every sea tile too costs a software renderer most of its frame rate.
    const data = Array.from({ length: map.heightTiles }, (_, tileY) =>
      Array.from({ length: map.widthTiles }, (_, tileX) => {
        const index = tileIndex(tileX, tileY);
        return index === TILE_SEA ? -1 : index;
      }),
    );
    const tilemap = this.make.tilemap({ data, tileWidth: TILE_PIXELS, tileHeight: TILE_PIXELS });
    const tiles = tilemap.addTilesetImage("terrain", "terrain-tiles", TILE_PIXELS, TILE_PIXELS, 0, 0)!;
    tilemap.createLayer(0, tiles, 0, 0);

    // A chart grid every eight tiles, so open water shows the ship's motion.
    const grid = this.add.graphics();
    grid.lineStyle(1, GRID_COLOR, 0.6);
    for (let tile = 0; tile <= map.widthTiles; tile += 8) grid.lineBetween(tile * TILE_PIXELS, 0, tile * TILE_PIXELS, WORLD_HEIGHT);
    for (let tile = 0; tile <= map.heightTiles; tile += 8) grid.lineBetween(0, tile * TILE_PIXELS, WORLD_WIDTH, tile * TILE_PIXELS);

    for (const island of map.islands) {
      const label = this.add.text((island.tileX + island.widthTiles / 2) * TILE_PIXELS, (island.tileY - 1.2) * TILE_PIXELS, island.name, {
        fontFamily: "system-ui, sans-serif",
        fontSize: `${12 * ART_SCALE}px`,
        color: "#e8f1f5",
      });
      label.setOrigin(0.5, 0.5).setAlpha(0.85);
    }
  }

  /** The minimap: one pixel per tile, fogged until the player's ship has seen it. */
  private createMinimap(): void {
    this.minimap = this.textures.createCanvas("minimap", map.widthTiles, map.heightTiles)!;
    const context = this.minimap.getContext();
    context.fillStyle = cssColor(FOG_COLOR);
    context.fillRect(0, 0, map.widthTiles, map.heightTiles);
    this.minimap.refresh();
    const left = VIEW_WIDTH - MINIMAP_MARGIN - map.widthTiles * MINIMAP_SCALE;
    const frame = this.add.graphics().setScrollFactor(0).setDepth(10);
    frame.lineStyle(2, 0x9bb8c6, 0.9);
    frame.strokeRect(left - 1, MINIMAP_MARGIN - 1, map.widthTiles * MINIMAP_SCALE + 2, map.heightTiles * MINIMAP_SCALE + 2);
    this.add.image(left, MINIMAP_MARGIN, "minimap").setOrigin(0, 0).setScale(MINIMAP_SCALE).setScrollFactor(0).setDepth(10);
    this.minimapMarks = this.add.graphics().setScrollFactor(0).setDepth(11);
    this.report.dataset["minimap"] = `${left},${MINIMAP_MARGIN},${MINIMAP_SCALE}`;
  }

  private revealFog(x: number, y: number): void {
    const fresh = this.fog.revealAround(Math.floor(x / TILE_PIXELS), Math.floor(y / TILE_PIXELS));
    if (fresh.length === 0) return;
    const context = this.minimap.getContext();
    for (const [tileX, tileY] of fresh) {
      context.fillStyle = cssColor(tileColor(tileX, tileY));
      context.fillRect(tileX, tileY, 1, 1);
    }
    this.minimap.refresh();
    this.report.dataset["fogRevealed"] = String(this.fog.revealedCount);
  }

  override update(): void {
    const now = performance.now();
    const own = this.view.renderPosition(this.view.selfId, now);
    if (own !== undefined) {
      const x = own.x * PIXELS_PER_SUB_UNIT;
      const y = own.y * PIXELS_PER_SUB_UNIT;
      const scroll = followScroll(x, y);
      this.cameras.main.setScroll(scroll.x, scroll.y);
      this.sight.setPosition(x, y);
      this.revealFog(x, y);
    }
    const camera = this.cameras.main;
    const minimapLeft = VIEW_WIDTH - MINIMAP_MARGIN - map.widthTiles * MINIMAP_SCALE;
    this.minimapMarks.clear();

    const drawn: DrawnShip[] = [];
    const present = new Set<string>();
    for (const ship of this.view.ships()) {
      const position = this.view.renderPosition(ship.id, now);
      if (position === undefined) continue;
      present.add(ship.id);
      const mine = ship.id === this.view.selfId;
      let graphics = this.shipGraphics.get(ship.id);
      if (graphics === undefined) {
        graphics = this.drawShip(slotColor(ship.slot), mine);
        this.shipGraphics.set(ship.id, graphics);
      }
      const x = position.x * PIXELS_PER_SUB_UNIT;
      const y = position.y * PIXELS_PER_SUB_UNIT;
      graphics.setPosition(x, y);
      graphics.setRotation((ship.heading * 2 * Math.PI) / HEADING_COUNT);
      drawn.push({ id: ship.id, x: Math.round(x - camera.scrollX), y: Math.round(y - camera.scrollY), color: cssColor(slotColor(ship.slot)) });
      this.minimapMarks.fillStyle(mine ? OWN_RING_COLOR : slotColor(ship.slot), 1);
      this.minimapMarks.fillRect(minimapLeft + (x / TILE_PIXELS) * MINIMAP_SCALE - 1.5, MINIMAP_MARGIN + (y / TILE_PIXELS) * MINIMAP_SCALE - 1.5, 3, 3);
    }
    for (const [id, graphics] of this.shipGraphics) {
      if (present.has(id)) continue;
      graphics.destroy();
      this.shipGraphics.delete(id);
    }
    const report = JSON.stringify(drawn);
    if (report !== this.lastReport) {
      this.report.dataset["drawnShips"] = report;
      this.lastReport = report;
    }
    this.report.dataset["camera"] = `${camera.scrollX},${camera.scrollY}`;
  }

  /** A round hull with a bow pointing along +x; the player's own ship gets a pale ring. */
  private drawShip(color: number, own: boolean): Phaser.GameObjects.Graphics {
    const graphics = this.add.graphics();
    graphics.setDepth(2);
    graphics.fillStyle(color, 1);
    graphics.fillCircle(0, 0, 6 * ART_SCALE);
    graphics.fillTriangle(3 * ART_SCALE, -5 * ART_SCALE, 12 * ART_SCALE, 0, 3 * ART_SCALE, 5 * ART_SCALE);
    if (own) {
      graphics.lineStyle(2, OWN_RING_COLOR, 1);
      graphics.strokeCircle(0, 0, 10 * ART_SCALE);
    }
    return graphics;
  }
}

export function startGame(parent: HTMLElement, view: MatchView): Phaser.Game {
  return new Phaser.Game({
    type: Phaser.AUTO,
    parent,
    width: VIEW_WIDTH,
    height: VIEW_HEIGHT,
    backgroundColor: SEA_COLOR,
    banner: false,
    audio: { noAudio: true },
    scene: new SeaScene(view, parent),
  });
}
import * as Phaser from "phaser";
import { defaultDuelConfig, findMove, worldBox, type DuelState, type FighterState, type WorldBox } from "@pirate-sea-race/simulation/duel";
import type { DuelFeedEvent } from "@pirate-sea-race/simulation/netcode";
import { ArenaFlashes, type ArenaFlash } from "./duelEvents.js";
import { cssColor } from "./matchView.js";

const { moveset } = defaultDuelConfig;
const SUB = moveset.arena.subPixelsPerPixel;
export const ARENA_WIDTH = moveset.arena.width / SUB;
export const ARENA_HEIGHT = 320;
/** The floor's height on the canvas, in pixels from the top. */
const FLOOR = ARENA_HEIGHT - 40;

export const FIGHTER_COLORS = [0xf4b942, 0x3dd6d0] as const;
const BACKGROUND = 0x1b2a38;
const FLOOR_COLOR = 0x3b5266;
const HURTBOX_COLOR = 0x46e06b;
const HITBOX_COLOR = 0xff3b30;
const PUSHBOX_COLOR = 0x6aa9ff;

/** What the arena draws from: the client's predicted duel, its fresh events, and the view options. */
export interface ArenaSource {
  /** The predicted state to draw, or undefined before the duel exists. */
  state(): DuelState | undefined;
  /** Events of newly simulated frames, each once (stable ids). */
  drainEvents(): DuelFeedEvent[];
  /** The predicted state of an earlier frame, while the client still holds it. */
  stateAt(frame: number): DuelState | undefined;
  /** The developer toggle: draw hurtboxes, pushboxes and active hitboxes. */
  showBoxes(): boolean;
  /** Big centred text: the countdown, or the result. */
  banner(): string;
}

/** A fighter as drawn this frame, for the DOM report the browser tests read. */
export interface DrawnFighter {
  readonly x: number;
  readonly y: number;
  readonly action: string;
  readonly moveId: string | null;
  readonly facing: number;
  readonly health: number;
}

/** Arena pixels of a box in sub-pixels (y up from the floor). */
function toCanvas(box: WorldBox): { x: number; y: number; w: number; h: number } {
  return { x: box.x0 / SUB, y: FLOOR - box.y1 / SUB, w: (box.x1 - box.x0) / SUB, h: (box.y1 - box.y0) / SUB };
}

function stance(fighter: FighterState): "standing" | "crouching" | "airborne" {
  if (fighter.y > 0 || fighter.vy > 0 || fighter.action === "jump") return "airborne";
  return fighter.crouching ? "crouching" : "standing";
}

/** The fighter's active hitbox this frame, if its move is on an active frame. */
function activeHitbox(fighter: FighterState): WorldBox | undefined {
  if (fighter.action !== "attack" || fighter.moveId === null) return undefined;
  const move = findMove(moveset, fighter.moveId);
  const frame = fighter.actionFrame;
  const active = typeof move.timing.active === "number" ? move.timing.active : 0;
  if (frame <= move.timing.startup || frame > move.timing.startup + active) return undefined;
  return worldBox(move.hitbox, fighter.x, fighter.y, fighter.facing);
}

/** The outline colour that tells the fighter's state at a glance. */
function stateColor(fighter: FighterState): number {
  switch (fighter.action) {
    case "hitstun":
    case "knockdown":
      return 0xff5a4f;
    case "blockstun":
      return 0xffffff;
    case "stagger":
      return 0xff9f1c;
    case "thrown":
    case "throw-break":
      return 0xc77dff;
    case "attack":
      return activeHitbox(fighter) === undefined ? 0xfff3b0 : 0xff3b30;
    default:
      return 0x0b1620;
  }
}

function actionLabel(fighter: FighterState): string {
  if (fighter.action === "attack" && fighter.moveId !== null) {
    const move = findMove(moveset, fighter.moveId);
    return `${move.timing.name} ${fighter.actionFrame}`;
  }
  return fighter.crouching && fighter.action !== "crouch" ? `${fighter.action} (low)` : fighter.action;
}

/**
 * The duel arena with placeholder shapes: each fighter is its stance's hurtbox in its colour, outlined by its state
 * (red when hit, white when blocking, yellow in startup, red while its hitbox is active), with a nose on the side it
 * faces and its current move above it. The developer toggle adds every hurtbox, pushbox and active hitbox. Hits,
 * blocks, throws and the KO flash once each, by their stable event ids (`ArenaFlashes`). The scene reports what it
 * drew as data attributes on its parent (`data-fighters`, `data-boxes`, `data-frame`) for the browser tests.
 */
export class ArenaScene extends Phaser.Scene {
  private graphics!: Phaser.GameObjects.Graphics;
  private boxes!: Phaser.GameObjects.Graphics;
  private labels: Phaser.GameObjects.Text[] = [];
  private bannerText!: Phaser.GameObjects.Text;
  private readonly flashes = new ArenaFlashes();
  private readonly flashTexts = new Map<string, Phaser.GameObjects.Text>();
  private lastReport = "";
  /** Frames whose active hitbox was drawn, since the page loaded. */
  private hitboxFrames = 0;
  /** The frame drawn last: hitboxes of the frames stepped since then are drawn too, so a slow render misses none. */
  private lastDrawnFrame = -1;

  constructor(
    private readonly source: ArenaSource,
    private readonly report: HTMLElement,
  ) {
    super("arena");
  }

  create(): void {
    const floor = this.add.graphics();
    floor.fillStyle(FLOOR_COLOR, 1);
    floor.fillRect(0, FLOOR, ARENA_WIDTH, ARENA_HEIGHT - FLOOR);
    this.graphics = this.add.graphics().setDepth(1);
    this.boxes = this.add.graphics().setDepth(2);
    const style = { fontFamily: "system-ui, sans-serif", fontSize: "12px", color: "#e8f1f5" };
    this.labels = [this.add.text(0, 0, "", style).setOrigin(0.5, 1).setDepth(3), this.add.text(0, 0, "", style).setOrigin(0.5, 1).setDepth(3)];
    this.bannerText = this.add
      .text(ARENA_WIDTH / 2, 90, "", { fontFamily: "system-ui, sans-serif", fontSize: "36px", color: "#fff3b0" })
      .setOrigin(0.5, 0.5)
      .setDepth(4);
  }

  override update(time: number): void {
    const state = this.source.state();
    this.graphics.clear();
    this.boxes.clear();
    this.bannerText.setText(this.source.banner());
    if (state === undefined) return;
    const showBoxes = this.source.showBoxes();
    let hurtboxes = 0;
    let hitboxes = 0;
    state.fighters.forEach((fighter, index) => {
      const body = toCanvas(worldBox(moveset.fighter.hurtboxes[stance(fighter)], fighter.x, fighter.y, fighter.facing));
      const knockedDown = fighter.action === "knockdown";
      this.graphics.fillStyle(FIGHTER_COLORS[index]!, 1);
      if (knockedDown) this.graphics.fillRect(body.x - body.h / 4, FLOOR - body.w / 2, body.h / 2, body.w / 2);
      else this.graphics.fillRect(body.x, body.y, body.w, body.h);
      this.graphics.lineStyle(3, stateColor(fighter), 1);
      if (!knockedDown) this.graphics.strokeRect(body.x, body.y, body.w, body.h);
      // The nose: which way the fighter faces.
      const noseX = fighter.facing === 1 ? body.x + body.w : body.x;
      this.graphics.fillStyle(0x0b1620, 1);
      this.graphics.fillTriangle(noseX, body.y + 10, noseX + 8 * fighter.facing, body.y + 16, noseX, body.y + 22);
      this.labels[index]!.setPosition(body.x + body.w / 2, body.y - 4).setText(actionLabel(fighter));

      if (!showBoxes) return;
      hurtboxes++;
      this.boxes.lineStyle(2, HURTBOX_COLOR, 1);
      this.boxes.strokeRect(body.x - 3, body.y - 3, body.w + 6, body.h + 6);
      const { halfWidth, height } = moveset.fighter.pushbox;
      const push = toCanvas({ x0: fighter.x - halfWidth, x1: fighter.x + halfWidth, y0: fighter.y, y1: fighter.y + height });
      this.boxes.lineStyle(1, PUSHBOX_COLOR, 0.8);
      this.boxes.strokeRect(push.x, push.y, push.w, push.h);
    });
    if (showBoxes) {
      // Every active hitbox since the last picture: at 60 fps just this frame's, on a slower render the skipped ones too.
      const first = Math.min(state.frame, Math.max(this.lastDrawnFrame + 1, state.frame - 60));
      for (let frame = first; frame <= state.frame; frame++) {
        const past = frame === state.frame ? state : this.source.stateAt(frame);
        const active = past?.fighters.map(activeHitbox).filter((box) => box !== undefined) ?? [];
        if (active.length > 0 && frame > this.lastDrawnFrame) this.hitboxFrames++;
        for (const hit of active) {
          if (frame === state.frame) hitboxes++;
          const box = toCanvas(hit);
          this.boxes.fillStyle(HITBOX_COLOR, frame === state.frame ? 0.6 : 0.3);
          this.boxes.fillRect(box.x, box.y, box.w, box.h);
        }
      }
    }
    this.lastDrawnFrame = state.frame;

    for (const flash of this.flashes.add(this.source.drainEvents(), time)) this.flash(flash, state);
    for (const flash of this.flashes.expire(time)) {
      this.flashTexts.get(flash.id)?.destroy();
      this.flashTexts.delete(flash.id);
    }

    const drawn: DrawnFighter[] = state.fighters.map((fighter) => ({
      x: fighter.x,
      y: fighter.y,
      action: fighter.action,
      moveId: fighter.moveId,
      facing: fighter.facing,
      health: fighter.health,
    }));
    const report = JSON.stringify(drawn);
    if (report !== this.lastReport) {
      this.report.dataset["fighters"] = report;
      this.lastReport = report;
    }
    this.report.dataset["frame"] = String(state.frame);
    this.report.dataset["boxes"] = JSON.stringify({ shown: showBoxes, hurtboxes, hitboxes, hitboxFrames: this.hitboxFrames });
  }

  /** A short text over the fighter an event happened to (the flash's text and lifetime come from `flashFor`). */
  private flash(flash: ArenaFlash, state: DuelState): void {
    const x = flash.over === "centre" ? ARENA_WIDTH / 2 : state.fighters[flash.over].x / SUB;
    const y = flash.over === "centre" ? 140 : FLOOR - 120;
    const label = this.add.text(x, y, flash.text, { fontFamily: "system-ui, sans-serif", fontSize: "18px", color: cssColor(0xfff3b0) }).setOrigin(0.5, 0.5).setDepth(5);
    this.flashTexts.set(flash.id, label);
  }
}

/**
 * The arena is a few flat shapes, so it uses Phaser's canvas renderer: without a GPU (a software WebGL) WebGL would
 * cost the main thread tens of milliseconds a frame, which the client's 4 ms tick and the round-trip probes share.
 */
export function startArena(parent: HTMLElement, source: ArenaSource): Phaser.Game {
  return new Phaser.Game({
    type: Phaser.CANVAS,
    parent,
    width: ARENA_WIDTH,
    height: ARENA_HEIGHT,
    backgroundColor: BACKGROUND,
    banner: false,
    audio: { noAudio: true },
    scene: new ArenaScene(source, parent),
  });
}

export { HITBOX_COLOR, HURTBOX_COLOR };

