import { dockLabel } from "@pirate-sea-race/content";
import { defaultSimulationConfig, dockInReach, NOT_DOCKED, toTilePosition } from "@pirate-sea-race/simulation";
import { cssColor, slotColor, type ShipSnapshot } from "./matchView.js";

export type ConnectionStatus = "connected" | "disconnected";

export interface HudModel {
  readonly code: string;
  readonly protocolVersion: number;
  readonly custom: boolean;
  readonly status: ConnectionStatus;
  readonly selfId: string;
  /** Players in the match, including those out of sight. */
  readonly players: number;
  /** The ships the server sent: the player's own and those in sight. */
  readonly ships: readonly ShipSnapshot[];
}

function field(root: ParentNode, id: string): HTMLElement {
  const element = root.querySelector<HTMLElement>(`[data-testid="${id}"]`);
  if (element === null) throw new Error(`missing HUD field ${id}`);
  return element;
}

/** "Palm Key, south dock" when moored, "at sea" otherwise. */
export function dockText(dock: number): string {
  return dock === NOT_DOCKED ? "at sea" : dockLabel(defaultSimulationConfig.map, dock);
}

/**
 * What the player can do about docking right now, by the simulation's own rule (`dockInReach`; speed does not matter):
 * nothing to say when moored or far from any dock; otherwise press E.
 */
export function dockHint(ship: Pick<ShipSnapshot, "x" | "y" | "dock">): string {
  if (ship.dock !== NOT_DOCKED) return "";
  const config = defaultSimulationConfig;
  const berth = dockInReach(config, ship.x, ship.y);
  return berth === undefined ? "" : `Press E to dock at ${dockLabel(config.map, berth.id)}`;
}

/** Writes the match status and the latest authoritative (not interpolated) state of the visible ships. */
export function renderHud(root: ParentNode, model: HudModel): void {
  field(root, "hud-code").textContent = model.code;
  field(root, "hud-protocol").textContent = `v${model.protocolVersion}`;
  field(root, "hud-players").textContent = String(model.players);
  field(root, "hud-status").textContent = model.status;
  field(root, "hud-mode").textContent = model.custom ? "custom" : "standard";
  field(root, "hud-self").textContent = model.selfId;
  const own = model.ships.find((ship) => ship.id === model.selfId);
  const dock = field(root, "hud-dock");
  dock.textContent = own === undefined ? "" : dockText(own.dock);
  dock.dataset["dock"] = String(own?.dock ?? NOT_DOCKED);
  field(root, "hud-dock-hint").textContent = own === undefined ? "" : dockHint(own);

  const list = field(root, "positions");
  const items = model.ships.map((ship) => {
    const item = document.createElement("li");
    item.dataset["shipId"] = ship.id;
    item.dataset["slot"] = String(ship.slot);
    item.dataset["x"] = String(ship.x);
    item.dataset["y"] = String(ship.y);
    item.dataset["heading"] = String(ship.heading);
    item.dataset["speed"] = String(ship.speed);
    item.dataset["dock"] = String(ship.dock);
    const swatch = document.createElement("span");
    swatch.className = "swatch";
    swatch.style.background = cssColor(slotColor(ship.slot));
    const tile = toTilePosition(defaultSimulationConfig, ship.x, ship.y);
    const who = ship.id === model.selfId ? "you" : ship.id;
    item.append(swatch, `${who}: tile ${tile.tileX},${tile.tileY}, heading ${ship.heading}, speed ${ship.speed}`);
    return item;
  });
  list.replaceChildren(...items);
}
import type { DuelRoomPhase } from "@pirate-sea-race/protocol";
import type { DuelState, PlayerIndex } from "@pirate-sea-race/simulation/duel";

export type DuelConnectionStatus = "connected" | "reconnecting" | "disconnected";

export interface DuelHudModel {
  readonly code: string;
  readonly practice: boolean;
  readonly phase: DuelRoomPhase;
  readonly status: DuelConnectionStatus;
  /** This browser's player, 0 or 1. */
  readonly self: PlayerIndex;
  /** Frames left in the countdown. */
  readonly countdown: number;
  /** Seats connected, by player. */
  readonly connected: readonly [boolean, boolean];
  /** The newest state stepped from the server's confirmed inputs: the authoritative health, stamina and clock. */
  readonly confirmed: DuelState;
  readonly maxHealth: number;
  readonly maxStamina: number;
  readonly roundFrames: number;
  readonly overtimeFrames: number;
  readonly rttMs: number;
  readonly inputDelay: number;
  readonly corrections: number;
  readonly result: { readonly winner: number; readonly reason: string } | undefined;
}

function field(root: ParentNode, id: string): HTMLElement {
  const element = root.querySelector<HTMLElement>(`[data-testid="${id}"]`);
  if (element === null) throw new Error(`missing duel HUD field ${id}`);
  return element;
}

/**
 * The round clock in whole seconds (§7: 60 seconds, then 10 of overtime on equal health). It reads 0 on the round's
 * last frame, where a timeout is decided; overtime starts on the frame after.
 */
export function roundClock(frame: number, roundFrames: number, overtimeFrames: number): { seconds: number; overtime: boolean } {
  if (frame <= roundFrames) return { seconds: Math.ceil((roundFrames - frame) / 60), overtime: false };
  return { seconds: Math.max(0, Math.ceil((roundFrames + overtimeFrames - frame) / 60)), overtime: true };
}

const REASONS: Record<string, string> = {
  ko: "KO",
  "double-ko": "double KO",
  timeout: "time",
  overtime: "overtime",
  forfeit: "forfeit",
};

/** "Player 1 wins by KO", "Draw (double KO)", and "Both forfeit: no winner" when both forfeited on the same frame (§12). */
export function resultText(winner: number, reason: string): string {
  if (winner < 0 && reason === "forfeit") return "Both forfeit: no winner";
  const how = REASONS[reason] ?? reason;
  return winner < 0 ? `Draw (${how})` : `Player ${winner + 1} wins by ${how}`;
}

function playerName(model: DuelHudModel, player: PlayerIndex): string {
  if (player === model.self) return `Player ${player + 1} (you)`;
  return model.practice ? `Player ${player + 1} (dummy)` : `Player ${player + 1}`;
}

/**
 * The duel HUD (§13): both health bars and stamina, the round clock and the connection line, all from the confirmed
 * (server-equal) state, then the result. Data attributes carry the exact numbers for the browser tests.
 */
export function renderDuelHud(root: ParentNode, model: DuelHudModel): void {
  field(root, "duel-code").textContent = model.practice ? `${model.code} (practice)` : model.code;
  field(root, "duel-status").textContent = model.status;
  const phase = field(root, "duel-phase");
  phase.textContent = model.phase === "countdown" ? `Fight in ${Math.ceil(model.countdown / 60)}` : model.phase;
  phase.dataset["phase"] = model.phase;

  for (const player of [0, 1] as const) {
    const fighter = model.confirmed.fighters[player];
    field(root, `duel-name-${player}`).textContent = `${playerName(model, player)}${model.practice && player === 1 ? "" : model.connected[player] ? "" : " (away)"}`;
    const health = field(root, `duel-health-${player}`);
    health.dataset["value"] = String(fighter.health);
    health.style.setProperty("--fill", `${(100 * fighter.health) / model.maxHealth}%`);
    field(root, `duel-health-text-${player}`).textContent = `${fighter.health} / ${model.maxHealth}`;
    const stamina = field(root, `duel-stamina-${player}`);
    stamina.dataset["value"] = String(fighter.stamina);
    stamina.style.setProperty("--fill", `${(100 * fighter.stamina) / model.maxStamina}%`);
  }

  const clock = roundClock(model.confirmed.frame, model.roundFrames, model.overtimeFrames);
  const clockField = field(root, "duel-clock");
  clockField.textContent = clock.overtime ? `OT ${clock.seconds}` : String(clock.seconds);
  clockField.dataset["frame"] = String(model.confirmed.frame);
  clockField.dataset["seconds"] = String(clock.seconds);

  field(root, "duel-rtt").textContent = `${Math.round(model.rttMs)} ms`;
  field(root, "duel-delay").textContent = model.inputDelay > 0 ? `${model.inputDelay} frames` : "measuring";
  field(root, "duel-delay").dataset["frames"] = String(model.inputDelay);
  field(root, "duel-corrections").textContent = String(model.corrections);
  field(root, "duel-corrections").dataset["count"] = String(model.corrections);

  const result = field(root, "duel-result");
  result.hidden = model.result === undefined;
  if (model.result !== undefined) {
    field(root, "duel-result-text").textContent = resultText(model.result.winner, model.result.reason);
    result.dataset["winner"] = String(model.result.winner);
    result.dataset["reason"] = model.result.reason;
    result.dataset["frame"] = String(model.confirmed.frame);
    result.dataset["health"] = model.confirmed.fighters.map((fighter) => fighter.health).join(",");
  }
}
import { Buttons } from "@pirate-sea-race/protocol";

/** What the player asks of their ship: protocol axes (moveX turns, moveY is the throttle, up ahead) and buttons. */
export interface Helm {
  readonly moveX: number;
  readonly moveY: number;
  readonly buttons: number;
}

export const NEUTRAL_HELM: Helm = { moveX: 0, moveY: 0, buttons: 0 };

const KEYS = {
  left: ["KeyA", "ArrowLeft"],
  right: ["KeyD", "ArrowRight"],
  up: ["KeyW", "ArrowUp"],
  down: ["KeyS", "ArrowDown"],
  interact: ["KeyE"],
} as const;

const HELM_CODES = new Set<string>(Object.values(KEYS).flat());

/** Converts two opposing keys into one axis: both held is neutral, whatever order they were pressed in (§8). */
export function axis(negative: boolean, positive: boolean): number {
  return (positive ? 1 : 0) - (negative ? 1 : 0);
}

/**
 * The keyboard input adapter (§8 defaults): up is throttle, down brakes (and reverses slowly from a stop), left and
 * right turn, E interacts (docks). It tracks held keys and releases them all (and forgets a tap) when the window loses
 * focus, so a ship never keeps sailing, or docks, on a key the page missed. The page reads it on a timer, so a tap of E that goes down and up
 * between two reads is kept until the next read, as the duel keyboard keeps its taps: it counts once.
 */
export class KeyboardHelm {
  private readonly held = new Set<string>();
  private tapped = 0;

  constructor(target: Window) {
    target.addEventListener("keydown", (event) => {
      if (!HELM_CODES.has(event.code) || isTyping(event.target)) return;
      event.preventDefault();
      this.press(event.code);
    });
    target.addEventListener("keyup", (event) => this.release(event.code));
    target.addEventListener("blur", () => {
      this.held.clear();
      this.tapped = 0;
    });
  }

  press(code: string): void {
    if (!HELM_CODES.has(code)) return;
    this.held.add(code);
    if ((KEYS.interact as readonly string[]).includes(code)) this.tapped |= Buttons.Interact;
  }

  release(code: string): void {
    this.held.delete(code);
  }

  /** What is held now, plus a button tapped since the last read. Reading it clears the tap. */
  helm(): Helm {
    const any = (codes: readonly string[]) => codes.some((code) => this.held.has(code));
    const buttons = (any(KEYS.interact) ? Buttons.Interact : 0) | this.tapped;
    this.tapped = 0;
    return {
      moveX: axis(any(KEYS.left), any(KEYS.right)),
      moveY: axis(any(KEYS.up), any(KEYS.down)),
      buttons,
    };
  }
}

/** Whether a key went to a text field. Outside a browser (unit tests in Node) there are no text fields. */
function isTyping(target: EventTarget | null): boolean {
  return (
    (typeof HTMLInputElement !== "undefined" && target instanceof HTMLInputElement) ||
    (typeof HTMLTextAreaElement !== "undefined" && target instanceof HTMLTextAreaElement)
  );
}
import { MAX_INPUT_LEAD_FRAMES, MessageType, type InputMessage } from "@pirate-sea-race/protocol";
import { STEPS_PER_SECOND } from "@pirate-sea-race/simulation";
import { NEUTRAL_HELM, type Helm } from "./keyboard.js";

/** Resend a held input this often, well inside the server's 250 ms hold window. */
const REFRESH_MS = 100;
/** Never tag an input further ahead than half the server's future-frame window. */
const MAX_ESTIMATE_LEAD = Math.floor(MAX_INPUT_LEAD_FRAMES / 2);

/** The client's estimate of the server's current frame: the last patched frame plus the time since it arrived. */
export function estimateServerFrame(patchedFrame: number, patchedAt: number, now: number): number {
  const elapsed = Math.max(0, Math.floor(((now - patchedAt) * STEPS_PER_SECOND) / 1000));
  return patchedFrame + Math.min(elapsed, MAX_ESTIMATE_LEAD);
}

export interface InputChannel {
  send(type: string, message: InputMessage): void;
}

/** Sends the player's intent: on every change, and repeated while a key is held. */
export class InputSender {
  private seq = 0;
  private last: Helm = NEUTRAL_HELM;
  private lastSentAt = Number.NEGATIVE_INFINITY;
  private patchedFrame = 0;
  private patchedAt = 0;

  constructor(private readonly channel: InputChannel) {}

  observeFrame(frame: number, now: number): void {
    if (frame !== this.patchedFrame) {
      this.patchedFrame = frame;
      this.patchedAt = now;
    }
  }

  update(helm: Helm, now: number): void {
    const changed = helm.moveX !== this.last.moveX || helm.moveY !== this.last.moveY || helm.buttons !== this.last.buttons;
    const held = helm.moveX !== 0 || helm.moveY !== 0 || helm.buttons !== 0;
    if (!changed && !(held && now - this.lastSentAt >= REFRESH_MS)) return;
    this.channel.send(MessageType.Input, {
      seq: ++this.seq,
      frame: estimateServerFrame(this.patchedFrame, this.patchedAt, now),
      buttons: helm.buttons,
      moveX: helm.moveX,
      moveY: helm.moveY,
    });
    this.last = helm;
    this.lastSentAt = now;
  }
}
import { INTERPOLATION_DELAY_MS, SnapshotBuffer } from "./interpolation.js";

/** A ship as the server last sent it: only the client's own ship and ships in its sight ever arrive (§16). */
export interface ShipSnapshot {
  readonly id: string;
  readonly slot: number;
  readonly x: number;
  readonly y: number;
  readonly heading: number;
  readonly speed: number;
  /** The dock it is moored at, or -1 at sea. */
  readonly dock: number;
}

/** Placeholder ship colours by spawn slot. */
const SLOT_COLORS = [0xf4b942, 0xe5484d, 0x46a758, 0xb66ee8, 0xf76b15, 0x3dd6d0, 0xf2f2f2, 0xd6409f] as const;

export function slotColor(slot: number): number {
  return SLOT_COLORS[slot % SLOT_COLORS.length]!;
}

export function cssColor(color: number): string {
  return `#${color.toString(16).padStart(6, "0")}`;
}

/**
 * The client's picture of the match: the latest decoded server state of each visible ship (for the HUD) and a
 * snapshot history per ship (for interpolated drawing). A ship that leaves the decoded state is forgotten at once.
 */
export class MatchView {
  private readonly latest = new Map<string, ShipSnapshot>();
  private readonly buffers = new Map<string, SnapshotBuffer>();

  constructor(readonly selfId: string) {}

  ingest(ships: Iterable<ShipSnapshot>, now: number): void {
    const seen = new Set<string>();
    for (const ship of ships) {
      seen.add(ship.id);
      const { id, slot, x, y, heading, speed, dock } = ship;
      this.latest.set(id, { id, slot, x, y, heading, speed, dock });
      let buffer = this.buffers.get(id);
      if (buffer === undefined) this.buffers.set(id, (buffer = new SnapshotBuffer()));
      buffer.push(now, x, y);
    }
    for (const id of [...this.latest.keys()]) {
      if (seen.has(id)) continue;
      this.latest.delete(id);
      this.buffers.delete(id);
    }
  }

  ships(): ShipSnapshot[] {
    return [...this.latest.values()];
  }

  ship(id: string): ShipSnapshot | undefined {
    return this.latest.get(id);
  }

  /** Where to draw a ship at `now`, interpolated INTERPOLATION_DELAY_MS in the past. */
  renderPosition(id: string, now: number): { x: number; y: number } | undefined {
    return this.buffers.get(id)?.sample(now - INTERPOLATION_DELAY_MS);
  }
}
import type { Room } from "@colyseus/sdk";

/**
 * Development only (`npm run dev`; main.ts imports this module only when `import.meta.env.DEV`, so the production
 * build does not contain it): delays everything a room's socket sends and receives, the server's round-trip probes
 * and Colyseus's own pings included, by half of `rttMs` each way plus a uniform ±jitter/2, never reordering. It lets
 * the operator playtest §19's latencies on one machine: `?rtt=80&jitter=20`.
 */
export const DEV_LATENCY_MARKER = "pirate-sea-race dev latency";

export interface DevLatency {
  readonly rttMs: number;
  readonly jitterMs: number;
}

/** The setting from the page's query string, or undefined when it asks for none. */
export function devLatencyFromQuery(search: string): DevLatency | undefined {
  const query = new URLSearchParams(search);
  const rttMs = Number(query.get("rtt") ?? 0);
  const jitterMs = Number(query.get("jitter") ?? 0);
  if (!(rttMs > 0 || jitterMs > 0) || !Number.isFinite(rttMs) || !Number.isFinite(jitterMs)) return undefined;
  return { rttMs: Math.max(0, rttMs), jitterMs: Math.max(0, jitterMs) };
}

/** Where a delay line takes its time and its jitter from; tests pass a fake clock and a fixed sequence. */
export interface DelaySource {
  /** Milliseconds on a monotonic clock, the one `setTimeout` runs on. */
  readonly now: () => number;
  /** A uniform draw in [0, 1). */
  readonly random: () => number;
}

const REAL_TIME: DelaySource = { now: () => performance.now(), random: Math.random };

/**
 * An ordered delay line: each item is due half the round trip plus a uniform ±jitter/2 after it was pushed, and
 * leaves at the later of that and the previous item's time, so jitter only ever delays and never reorders. It uses
 * only `setTimeout`, no DOM, so Node tests load it as it is.
 */
export class DelayLine {
  private last = Number.NEGATIVE_INFINITY;

  constructor(
    private readonly latency: DevLatency,
    private readonly source: DelaySource = REAL_TIME,
  ) {}

  push(deliver: () => void): void {
    const now = this.source.now();
    const delay = Math.max(0, this.latency.rttMs / 2 + (this.source.random() - 0.5) * this.latency.jitterMs);
    const at = Math.max(this.last, now + delay);
    this.last = at;
    setTimeout(deliver, at - now);
  }
}

/**
 * Wraps a joined room's connection in both directions: everything the socket sends and everything it receives goes
 * through its own delay line. It survives the SDK's reconnection, which reuses both hooks.
 */
export function applyDevLatency(room: Room, latency: DevLatency, source: DelaySource = REAL_TIME): void {
  console.info(`${DEV_LATENCY_MARKER}: ${latency.rttMs} ms round trip, ${latency.jitterMs} ms jitter`);
  const connection = room.connection as unknown as {
    transport: { send(data: Uint8Array): void };
    events: { onmessage?: (event: unknown) => void };
  };
  const outgoing = new DelayLine(latency, source);
  const send = connection.transport.send.bind(connection.transport);
  connection.transport.send = (data: Uint8Array) => {
    const copy = new Uint8Array(data);
    outgoing.push(() => {
      try {
        send(copy);
      } catch {
        // The socket closed meanwhile; a real network would have lost it too.
      }
    });
  };
  const incoming = new DelayLine(latency, source);
  const receive = connection.events.onmessage;
  connection.events.onmessage = (event: unknown) => incoming.push(() => receive?.call(connection.events, event));
}

