import { duelistMoveset, KIT_IDS, movesetVersion, type DuelButton, type DuelKit, type DuelMove, type DuelMoveset, type KitId } from "@pirate-sea-race/content/moves";
import type { Facing } from "./boxes.js";

/** Static duel data the step reads; it never changes during a duel. */
export interface DuelConfig {
  readonly moveset: DuelMoveset;
}

export const defaultDuelConfig: DuelConfig = { moveset: duelistMoveset };

/**
 * What a fighter is doing. `idle`, `walk` and `crouch` are free: the fighter can start anything on the next frame.
 * `jump` lasts until landing. The others are timed by `timer`.
 */
export type FighterAction =
  | "idle"
  | "walk"
  | "crouch"
  | "jump"
  | "dash"
  | "backdash"
  | "attack"
  | "hitstun"
  | "blockstun"
  | "stagger"
  | "thrown"
  | "throw-break"
  | "knockdown";

export type Stance = "standing" | "crouching" | "airborne";

/** Frames each button press stays usable (0 = no press waiting). */
export type InputBuffer = Readonly<Record<DuelButton, number>>;

/**
 * A fighter's flying bolt (a `projectile` special's entity). At most one per fighter: the cast cannot start while it
 * flies. Its strike data is `moveId`'s `projectile`.
 */
export interface Bolt {
  /** The cast move that released it, one of its owner's kit specials. */
  readonly moveId: string;
  /** Position in sub-pixels; the bolt's box is placed here, facing the way it flies. */
  readonly x: number;
  readonly y: number;
  /** Sub-pixels per frame: plus or minus the projectile's speed. */
  readonly vx: number;
  /** Frames it still exists after the current one. */
  readonly life: number;
}

/**
 * A fighter's smoke screen (a `zone` special's entity). At most one per fighter: the cast cannot start while it lasts.
 * It never strikes; it marks the fighters inside it (`FighterState.obscured`).
 */
export interface Zone {
  /** The cast move that laid it, one of its owner's kit specials. */
  readonly moveId: string;
  /** The caster's origin and facing at the cast; the zone's box is placed there. */
  readonly x: number;
  readonly facing: Facing;
