  stopShip,''',1)
s=s.rstrip()+'''

describe("ships in encounters (§6)", () => {
  const berth = config.map.docks[0]!;
  const sailing = () => {
    let state = addShip(config, createMatchState(7), "a");
    state = placeShip(config, state, "a", { ...config.map.hub, heading: 0 });
    for (let frame = 0; frame < 30; frame++) state = step(config, state, { a: { buttons: 0, moveX: 0, moveY: -AXIS_SCALE } });
    return state;
  };

  it("keeps the grapple button apart from interact, and sailing ignores it", () => {
    expect(GRAPPLE_BUTTON & INTERACT_BUTTON).toBe(0);
    const state = sailing();
    const ship = state.ships[0]!;
    const input = { buttons: 0, moveX: 0, moveY: -AXIS_SCALE };
    expect(sail(config, ship, { ...input, buttons: GRAPPLE_BUTTON })).toEqual(sail(config, ship, input));
  });

  it("stops a reserved ship where it is, and it stays put on neutral input", () => {
    const state = sailing();
    expect(state.ships[0]!.speed).toBeGreaterThan(0);
    let held = stopShip(state, "a");
    const at = held.ships[0]!;
    expect(at).toMatchObject({ x: state.ships[0]!.x, y: state.ships[0]!.y, speed: 0 });
    for (let frame = 0; frame < 30; frame++) held = step(config, held, { a: { buttons: 0, moveX: 0, moveY: 0 } });
    expect(held.ships[0]).toEqual(at);
    expect(() => stopShip(state, "nobody")).toThrow();
  });

  it("returns a ship at rest to a point, or moored at its respawn dock, and refuses a point a hull does not fit", () => {
    const state = sailing();
    const dock = tileCentre(config, berth.tileX, berth.tileY);
    const moored = returnShip(config, state, "a", { ...dock, dock: berth.id });
